#!/bin/bash
# lambda_setup_t27.sh — one-time environment for the text27b notebook (genizah_t27_lambda.ipynb) on a Lambda instance.
# Generated by src/finetuning/qwen_hebrew/colab/derive_t27.py from host_lambda.PIN_SETS["text27b"] (status: exact).
# Exact pins record the resolved smoke environment; the notebook's G1 gate verifies them at runtime.
# Usage (JupyterLab -> Terminal):   bash lambda_setup_t27.sh
set -euo pipefail
VENV="$HOME/genizah-t27-venv"
command -v nvidia-smi >/dev/null || { echo "nvidia-smi not found: this is not a GPU instance"; exit 1; }
ARCH=$(uname -m)
[ "$ARCH" = "x86_64" ] || { echo "CPU architecture $ARCH is untested (GH200 is ARM): use an x86_64 instance"; exit 1; }
DRIVER=$(nvidia-smi --query-gpu=driver_version --format=csv,noheader | head -1 | cut -d. -f1)
# An exact CUDA wheel pin selects its matching index; otherwise choose by driver capability.
CUDA=cu128
echo "driver $DRIVER -> torch for $CUDA"
command -v uv >/dev/null || curl -LsSf https://astral.sh/uv/install.sh | sh
export PATH="$HOME/.local/bin:$PATH"
uv venv --python 3.13 "$VENV"
uv pip install --python "$VENV/bin/python" --index-url "https://download.pytorch.org/whl/$CUDA" "torch==2.11.0+cu128" "torchvision==0.26.0+cu128"
uv pip install --python "$VENV/bin/python" "unsloth==2026.10.7" "unsloth_zoo==2026.10.7" "transformers==5.17.0" "trl==1.15.0" "peft==0.21.2" "accelerate==1.15.0" "bitsandbytes==0.50.2" "flash-linear-attention==0.5.2" "datasets==4.8.5" "tokenizers==0.23.3" "safetensors==0.8.0" "huggingface_hub==1.33.0" "hf_transfer==0.1.9" "wandb==0.31.0" "torch==2.11.0+cu128" "torchvision==0.26.0+cu128" packaging ipykernel nbconvert
# Compile against this torch/CUDA build without replacing torch or reusing an incompatible wheel.
uv pip install --python "$VENV/bin/python" setuptools wheel ninja
CAUSAL_CONV1D_FORCE_BUILD=TRUE uv pip install --python "$VENV/bin/python" --no-deps --no-cache --no-binary causal-conv1d --no-build-isolation "causal-conv1d==1.7.0"
"$VENV/bin/python" -m ipykernel install --user --name genizah-t27 --display-name "genizah t27 (venv)"
mkdir -p "$HOME/genizah_work"
uv pip freeze --python "$VENV/bin/python" > "$HOME/genizah_work/t27_resolved_pins.txt"
"$VENV/bin/python" - unsloth unsloth_zoo transformers trl peft accelerate bitsandbytes flash-linear-attention causal-conv1d <<'PY'
import sys
from importlib.metadata import version
from importlib.util import find_spec
import torch
p = torch.cuda.get_device_properties(0)
print(f"torch {torch.__version__} on {p.name} ({p.total_memory / 2**30:.0f} GiB)")
for name in sys.argv[1:]:
    print(f"  {name} {version(name)}")
for module in ("fla", "causal_conv1d"):
    print(f"  {module}: {'importable' if find_spec(module) else 'MISSING'}")
PY
echo "kernel 'genizah t27 (venv)' ready; resolved versions in ~/genizah_work/t27_resolved_pins.txt"
echo "rung 1: write the versions above into host_lambda.PIN_SETS['text27b'] as exact pins and regenerate the notebook"
